   175→  timelineScrollPosition: 0,
   176→  thumbnailSize: 'medium',
   177→  showFrameNumbers: true,
   178→  showFrameDelays: false,
   179→  canvasZoom: 1.0,
   180→  canvasZoomPreset: '100',
