   201→
   202→const ZOOM_LEVELS = [0.25, 0.5, 0.75, 1.0, 1.5, 2.0, 3.0, 4.0];
   203→
   204→export const useEditorStore = create<EditorState & EditorActions>()(
   205→  subscribeWithSelector((set, get) => ({
   206→    ...initialState,
   207→
   208→    // Frame selection
   209→    selectFrame: (frameId, addToSelection = false) => {
   210→      set((state) => {
   211→        if (addToSelection) {
   212→          const newSelection = state.selectedFrameIds.includes(frameId)
   213→            ? state.selectedFrameIds.filter((id) => id !== frameId)
   214→            : [...state.selectedFrameIds, frameId];
   215→          return { selectedFrameIds: newSelection, lastSelectedFrameId: frameId };
   216→        }
   217→        return { selectedFrameIds: [frameId], lastSelectedFrameId: frameId };
   218→      });
   219→    },
   220→
   221→    selectFrames: (frameIds) => set({ selectedFrameIds: frameIds }),
