   256→    },
   257→
   258→    setCurrentFrameIndex: (currentFrameIndex) => set({ currentFrameIndex }),
   259→
   260→    nextFrame: () =>
   261→      set((state) => ({ currentFrameIndex: state.currentFrameIndex + 1 })),
   262→
   263→    previousFrame: () =>
   264→      set((state) => ({
   265→        currentFrameIndex: Math.max(0, state.currentFrameIndex - 1),
