   267→
   268→    goToFirstFrame: () => set({ currentFrameIndex: 0 }),
   269→
   270→    goToLastFrame: (totalFrames) =>
   271→      set({ currentFrameIndex: Math.max(0, totalFrames - 1) }),
   272→
   273→    setPlaybackSpeed: (playbackSpeed) =>
   274→      set({ playbackSpeed: Math.min(Math.max(playbackSpeed, 0.25), 4.0) }),
   275→
   276→    setIsLooping: (isLooping) => set({ isLooping }),
   277→
