   281→
   282→    setTimelineScrollPosition: (timelineScrollPosition) => set({ timelineScrollPosition }),
   283→
   284→    setThumbnailSize: (thumbnailSize) => set({ thumbnailSize }),
   285→    setShowFrameNumbers: (showFrameNumbers) => set({ showFrameNumbers }),
   286→    setShowFrameDelays: (showFrameDelays) => set({ showFrameDelays }),
   287→
   288→    // Canvas
   289→    setCanvasZoom: (canvasZoom) => set({ canvasZoom, canvasZoomPreset: 'fit' }),
   290→
   291→    setCanvasZoomPreset: (preset) => {
   292→      const zoomMap: Record<ZoomPreset, number | null> = {
   293→        fit: null,
   294→        fill: null,
   295→        '25': 0.25,
   296→        '50': 0.5,
   297→        '75': 0.75,
   298→        '100': 1.0,
   299→        '150': 1.5,
   300→        '200': 2.0,
   301→        '400': 4.0,
   302→      };
   303→      const zoom = zoomMap[preset];
   304→      if (zoom !== null) {
   305→        set({ canvasZoom: zoom, canvasZoomPreset: preset });
   306→      } else {
   307→        set({ canvasZoomPreset: preset });
   308→      }
   309→    },
   310→
   311→    zoomIn: () => {
   312→      const { canvasZoom } = get();
   313→      const nextIndex = ZOOM_LEVELS.findIndex((z) => z > canvasZoom);
   314→      if (nextIndex !== -1) {
   315→        set({ canvasZoom: ZOOM_LEVELS[nextIndex] });
   316→      }
   317→    },
   318→
   319→    zoomOut: () => {
   320→      const { canvasZoom } = get();
   321→      const prevIndex = [...ZOOM_LEVELS].reverse().findIndex((z) => z < canvasZoom);
   322→      if (prevIndex !== -1) {
   323→        set({ canvasZoom: ZOOM_LEVELS[ZOOM_LEVELS.length - 1 - prevIndex] });
   324→      }
   325→    },
