   330→    setCanvasPan: (canvasPanX, canvasPanY) => set({ canvasPanX, canvasPanY }),
   331→    setShowGrid: (showGrid) => set({ showGrid }),
   332→    setGridSize: (gridSize) => set({ gridSize }),
   333→    setSnapToGrid: (snapToGrid) => set({ snapToGrid }),
   334→
   335→    // Tools
   336→    setCurrentTool: (currentTool) => set({ currentTool }),
   337→    setToolOption: (key, value) =>
   338→      set((state) => ({ toolOptions: { ...state.toolOptions, [key]: value } })),
   339→    clearToolOptions: () => set({ toolOptions: {} }),
   340→
   341→    // Clipboard
   342→    copyFrames: (frameIds) => set({ clipboardFrameIds: frameIds, clipboardOperation: 'copy' }),
   343→    cutFrames: (frameIds) => set({ clipboardFrameIds: frameIds, clipboardOperation: 'cut' }),
   344→    clearClipboard: () => set({ clipboardFrameIds: [], clipboardOperation: null }),
   345→    hasClipboardContent: () => get().clipboardFrameIds.length > 0,
   346→
   347→    // History
   348→    setCanUndo: (canUndo) => set({ canUndo }),
   349→    setCanRedo: (canRedo) => set({ canRedo }),
   350→    setHistoryIndex: (historyIndex) => set({ historyIndex }),
   351→
