   347→        isDirty: true,
   348→      })),
   349→
   350→    // Sequence management
   351→    setSequences: (sequences) => set({ sequences, isDirty: true }),
   352→    addSequence: (sequence) =>
   353→      set((state) => ({ sequences: [...state.sequences, sequence], isDirty: true })),
   354→    removeSequence: (sequenceId) =>
   355→      set((state) => ({
   356→        sequences: state.sequences.filter((s) => s.id !== sequenceId),
   357→        isDirty: true,
   358→      })),
   359→    setActiveSequenceId: (activeSequenceId) => set({ activeSequenceId }),
   360→
   361→    // Track management
   362→    addTrack: (sequenceId, track) =>
   363→      set((state) => ({
   364→        sequences: state.sequences.map((s) =>
   365→          s.id === sequenceId ? { ...s, tracks: [...s.tracks, track] } : s
   366→        ),
   367→        isDirty: true,
   368→      })),
   369→
   370→    removeTrack: (sequenceId, trackId) =>
   371→      set((state) => ({
   372→        sequences: state.sequences.map((s) =>
   373→          s.id === sequenceId ? { ...s, tracks: s.tracks.filter((t) => t.id !== trackId) } : s
   374→        ),
   375→        isDirty: true,
   376→      })),
   377→
   378→    updateTrack: (sequenceId, trackId, updates) =>
   379→      set((state) => ({
   380→        sequences: state.sequences.map((s) =>
   381→          s.id === sequenceId
   382→            ? { ...s, tracks: s.tracks.map((t) => (t.id === trackId ? { ...t, ...updates } : t)) }
   383→            : s
   384→        ),
   385→        isDirty: true,
   386→      })),
   387→
   388→    // Recent projects
   389→    addRecentProject: (projectInfo) =>
   390→      set((state) => {
   391→        const filtered = state.recentProjects.filter((p) => p.path !== projectInfo.path);
   392→        const newRecent = [projectInfo, ...filtered].slice(0, state.maxRecentProjects);
   393→        return { recentProjects: newRecent };
   394→      }),
   395→
   396→    removeRecentProject: (path) =>
   397→      set((state) => ({
   398→        recentProjects: state.recentProjects.filter((p) => p.path !== path),
   399→      })),
   400→
   401→    clearRecentProjects: () => set({ recentProjects: [] }),
   402→
   403→    // Auto-save
   404→    setAutoSaveEnabled: (autoSaveEnabled) => set({ autoSaveEnabled }),
   405→    setAutoSaveInterval: (autoSaveInterval) => set({ autoSaveInterval }),
   406→
   407→    // History (undo/redo)
   408→    pushHistory: (entry) =>
   409→      set((state) => {
   410→        // Remove any redo history
   411→        const newHistory = state.history.slice(0, state.historyIndex + 1);
   412→        newHistory.push(entry);
   413→        // Trim to max size
   414→        if (newHistory.length > state.maxHistorySize) {
   415→          newHistory.shift();
   416→        }
   417→        return { history: newHistory, historyIndex: newHistory.length - 1 };
   418→      }),
   419→
   420→    undo: () => {
   421→      const { history, historyIndex } = get();
   422→      if (historyIndex >= 0) {
   423→        set({ historyIndex: historyIndex - 1 });
   424→        return history[historyIndex];
   425→      }
   426→      return null;
   427→    },
   428→
   429→    redo: () => {
   430→      const { history, historyIndex } = get();
   431→      if (historyIndex < history.length - 1) {
   432→        set({ historyIndex: historyIndex + 1 });
   433→        return history[historyIndex + 1];
   434→      }
   435→      return null;
   436→    },
   437→
   438→    clearHistory: () => set({ history: [], historyIndex: -1 }),
   439→    canUndo: () => get().historyIndex >= 0,
   440→    canRedo: () => get().historyIndex < get().history.length - 1,
   441→
   442→    // Error handling
   443→    setError: (error) => set({ error }),
   444→    addWarning: (warning) => set((state) => ({ warnings: [...state.warnings, warning] })),
   445→    clearWarnings: () => set({ warnings: [] }),
   446→
   447→    // Computed values
   448→    getTotalDuration: () => {
   449→      const { frames } = get();
   450→      return frames.reduce((sum, f) => sum + f.metadata.delay, 0);
   451→    },
   452→
   453→    getFrameById: (frameId) => get().frames.find((f) => f.id === frameId),
   454→    getFrameByIndex: (index) => get().frames[index],
   455→    getActiveSequence: () => {
   456→      const { sequences, activeSequenceId } = get();
   457→      return sequences.find((s) => s.id === activeSequenceId);
   458→    },
   459→
   460→    // Reset
   461→    reset: () => set(initialState),
   462→  }))
   463→);
   464→
   465→// Selector hooks
   466→export const selectHasProject = (state: ProjectState) => state.currentProject !== null;
   467→export const selectIsDirty = (state: ProjectState) => state.isDirty;
   468→export const selectFrameCount = (state: ProjectState) => state.totalFrameCount;
   469→export const selectProjectTitle = (state: ProjectState) =>
   470→  state.currentProject?.metadata.title ?? 'Untitled';
   471→

