    19→} from '../api/types';
    20→
    21→interface ExportState {
    22→  // Current export configuration
    23→  currentOptions: EncodingOptions | null;
    24→  selectedPresetId: string | null;
    25→  outputPath: string;
    26→  outputFileName: string;
    27→
    28→  // Presets
