    36→  encodingProgress: EncodingProgress | null;
    37→
    38→  // Export queue
    39→  queue: ExportQueueItem[];
    40→  isQueueProcessing: boolean;
    41→  maxConcurrentJobs: number;
    42→
    43→  // Upload state
    44→  isUploading: boolean;
    45→  uploadProgress: UploadProgress | null;
    46→  lastUploadResult: UploadResult | null;
    47→  uploadConfig: UploadConfig | null;
    48→
    49→  // Recent exports
    50→  recentExports: RecentExport[];
    51→  maxRecentExports: number;
    52→
    53→  // UI state
    54→  showAdvancedOptions: boolean;
    55→  selectedFormatTab: OutputFormat;
    56→
    57→  // Error state
    58→  error: string | null;
    59→}
    60→
    61→interface ExportActions {
    62→  // Configuration
    63→  setCurrentOptions: (options: EncodingOptions) => void;
    64→  updateCurrentOptions: (updates: Partial<EncodingOptions>) => void;
    65→  setSelectedPresetId: (presetId: string | null) => void;
    66→  setOutputPath: (path: string) => void;
    67→  setOutputFileName: (fileName: string) => void;
    68→  applyPreset: (preset: ExportPreset) => void;
    69→
    70→  // Presets
    71→  setBuiltInPresets: (presets: ExportPreset[]) => void;
    72→  addCustomPreset: (preset: ExportPreset) => void;
    73→  updateCustomPreset: (presetId: string, updates: Partial<ExportPreset>) => void;
    74→  removeCustomPreset: (presetId: string) => void;
    75→  setDefaultPresetId: (presetId: string | null) => void;
    76→  getPresetById: (presetId: string) => ExportPreset | undefined;
    77→  getPresetsByCategory: (category: PresetCategory) => ExportPreset[];
    78→
    79→  // Encoding
    80→  startEncoding: (jobId: string) => void;
    81→  updateEncodingProgress: (progress: EncodingProgress) => void;
    82→  completeEncoding: (success: boolean, error?: string) => void;
    83→  cancelEncoding: () => void;
    84→
    85→  // Queue
    86→  addToQueue: (item: Omit<ExportQueueItem, 'id' | 'status' | 'progress' | 'addedAt'>) => void;
